INSERT INTO users (id, name, email, password_hash, salt, created_at, username, display_name, bio, avatar_emoji, avatar_color, preferences, onboarded) VALUES ('auth-lea', 'Léa Moreau', 'lea_moreau@openlibrary.app', 'bd2574e7075005eb1deb574f2fab3fe4a8eb614981b0998dc4f67963f6ee0e8e', 'ffb0590b61500bf7d9777b7d430156e4', '2026-10-01T10:00:00.000Z', 'lea_moreau', 'Léa Moreau', 'Romance contemporaine et rencontres qui changent une vie.', '🌸', 'rose', '["Romance","Poésie"]', 1);
INSERT INTO books (id, owner_id, title, author, genre, description, cover, cover_style, tags, is_public, created_at, updated_at, views, impressions) VALUES ('auth-lea-b1', 'auth-lea', 'Lettres à demain', 'Léa Moreau', 'Romance', 'Deux inconnus s''écrivent chaque jour sans se voir. Jusqu''au jour où leurs lettres prédisent l''avenir.', 'rose', '{"preset":"rose","font":"serif","pattern":"none","layout":"classic","emoji":"💌","textColor":"#ffffff"}', '["épistolaire","slow burn","seconde chance"]', 1, '2026-10-01T10:00:00.000Z', '2026-10-01T10:00:00.000Z', 120, 300);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-lea-b1-c1', 'auth-lea-b1', 'Chapitre 1 — La boîte jaune', '<p>La boîte aux lettres du 12 rue des Lilas n''aurait jamais dû contenir autre chose que des factures. Pourtant, ce mardi, Salomé y trouva une enveloppe sans timbre, à son nom, d''une écriture inconnue.</p><p>« Chère inconnue, si tu lis ceci, c''est que la boîte a choisi. Écris-moi. — A. »</p><p>Elle rit, puis elle répondit. Après tout, qu''avait-elle à perdre ?</p>', 0, '2026-10-01T10:00:00.000Z', 62);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-lea-b1-c2', 'auth-lea-b1', 'Chapitre 2 — Le café de la gare', '<p>Trois jours plus tard, une réponse l''attendait. Au bas de la lettre, une phrase lui glaça le sang : <em>« Demain, il pleuvra, et tu oublieras ton parapluie au café. Prends-en un. »</em></p><p>Il pleuvait. Elle avait oublié le parapluie. Sur la table du café, un homme lisait, un carnet à la main.</p>', 1, '2026-10-01T10:00:00.000Z', 53);
INSERT INTO books (id, owner_id, title, author, genre, description, cover, cover_style, tags, is_public, created_at, updated_at, views, impressions) VALUES ('auth-lea-b2', 'auth-lea', 'Nos étés suspendus', 'Léa Moreau', 'Romance', 'Chaque été, ils se promettaient de ne jamais tomber amoureux. Cet été-là, la promesse vacilla.', 'amber', '{"preset":"amber","font":"hand","pattern":"dots","layout":"centered","emoji":"🌻","textColor":"#fde68a"}', '["vacances","amis to lovers"]', 1, '2026-10-01T10:00:00.000Z', '2026-10-01T10:00:00.000Z', 160, 420);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-lea-b2-c1', 'auth-lea-b2', 'Chapitre 1 — Le ponton', '<p>Ils avaient grandi sur ce ponton, entre les rires et les plongeons. « On ne tombera jamais amoureux », avaient-ils juré, les doigts croisés derrière le dos.</p><p>Puis vint cet été où tout changea.</p>', 0, '2026-10-01T10:00:00.000Z', 34);
INSERT INTO books (id, owner_id, title, author, genre, description, cover, cover_style, tags, is_public, created_at, updated_at, views, impressions) VALUES ('auth-lea-b3', 'auth-lea', 'Le Théorème du cœur', 'Léa Moreau', 'Romance', 'Une mathématicienne, un musicien, et une colocation qui ne devait durer qu''un semestre.', 'sky', '{"preset":"sky","font":"sans","pattern":"grid","layout":"band","emoji":"📐","textColor":"#e0f2fe"}', '["science","colocataires"]', 1, '2026-10-01T10:00:00.000Z', '2026-10-01T10:00:00.000Z', 200, 540);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-lea-b3-c1', 'auth-lea-b3', 'Chapitre 1 — Inconnus', '<p>La colocation était une variable d''ajustement : loyer trop cher, ville trop grande. Elle posa ses cartons, il accordait sa guitare.</p>', 0, '2026-10-01T10:00:00.000Z', 21);
