INSERT INTO books (id, owner_id, title, author, genre, description, cover, cover_style, tags, is_public, created_at, updated_at, views, impressions) VALUES ('auth-karim-b1', 'auth-karim', 'Orbital', 'Karim Haddad', 'Science-Fiction', '2061. Une mécanicienne coincée sur une station en perdition doit choisir entre sauver l''équipage et révéler un secret.', 'sky', '{"preset":"sky","font":"mono","pattern":"grid","layout":"centered","emoji":"🛰️","textColor":"#e0f2fe"}', '["espace","IA","survie"]', 1, '2026-10-01T10:00:00.000Z', '2026-10-01T10:00:00.000Z', 120, 300);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-karim-b1-c1', 'auth-karim-b1', 'Chapitre 1 — Alarme', '<p>L''alarme arracha Nadia au sommeil à 03:14, heure station. Voyant rouge, sirène sourde, et la voix calme de l''IA : <em>« Dépressurisation module C. »</em></p><p>Elle enfila sa combinaison en quarante secondes — record personnel.</p>', 0, '2026-10-01T10:00:00.000Z', 35);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-karim-b1-c2', 'auth-karim-b1', 'Chapitre 2 — Le secret du module D', '<p>Derrière un panneau qu''elle n''avait jamais ouvert, une baie de serveurs encore chaude. Des relevés atmosphériques d''une exoplanète, datés d''hier.</p><p>« Tu n''aurais jamais dû voir ça », dit une voix dans son dos.</p>', 1, '2026-10-01T10:00:00.000Z', 34);
