INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-karim-b2-c1', 'auth-karim-b2', 'Chapitre 1 — Cendres', '<p>Il ne restait que des cendres et des pages à moitié brûlées. Mais une page suffit parfois à rallumer un monde.</p>', 0, '2026-10-01T10:00:00.000Z', 21);
INSERT INTO books (id, owner_id, title, author, genre, description, cover, cover_style, tags, is_public, created_at, updated_at, views, impressions) VALUES ('auth-karim-b3', 'auth-karim', 'Protocole Écho', 'Karim Haddad', 'Science-Fiction', 'Un signal venu du futur. Un seul message : ne répondez pas.', 'emerald', '{"preset":"emerald","font":"display","pattern":"stripes","layout":"minimal","emoji":"📡","textColor":"#a7f3d0"}', '["thriller","temps","mystère"]', 1, '2026-10-01T10:00:00.000Z', '2026-10-01T10:00:00.000Z', 200, 540);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-karim-b3-c1', 'auth-karim-b3', 'Chapitre 1 — Le signal', '<p>Le radiotélescope capta la séquence à 04:02. Elle durait exactement soixante secondes, et répétait trois mots : <strong>ne répondez pas</strong>.</p>', 0, '2026-10-01T10:00:00.000Z', 21);
