INSERT INTO books (id, owner_id, title, author, genre, description, cover, cover_style, tags, is_public, created_at, updated_at, views, impressions) VALUES ('auth-camille-b1', 'auth-camille', 'La Cité des Brumes', 'Camille Petit', 'Fantastique', 'Après la disparition de son frère, Inès découvre une cité cachée où les souvenirs deviennent monnaie d''échange.', 'indigo', '{"preset":"indigo","font":"serif","pattern":"waves","layout":"classic","emoji":"🌫️","textColor":"#ffffff"}', '["magie","souvenirs","quête"]', 1, '2026-10-01T10:00:00.000Z', '2026-10-01T10:00:00.000Z', 120, 300);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-camille-b1-c1', 'auth-camille-b1', 'Chapitre 1 — La brume', '<p>Inès n''avait jamais cru aux histoires de sa grand-mère. Pas avant ce matin d''octobre où la brume a recouvert la vallée, épaisse comme du lait.</p><p>Sur le rebord de la fenêtre, une plume noire.</p>', 0, '2026-10-01T10:00:00.000Z', 34);
INSERT INTO chapters (id, book_id, title, content, position, updated_at, word_count) VALUES ('auth-camille-b1-c2', 'auth-camille-b1', 'Chapitre 2 — La porte', '<p>La porte était haute comme deux hommes, faite d''un bois veiné de lumière bleue. « Ici, on ne paie qu''en souvenirs », dit le vieil homme.</p>', 1, '2026-10-01T10:00:00.000Z', 26);
